type Node = { id: string; lat: number; lng: number; neighbors: string[] }

export function nextWaypoint(path: string[], index: number) {
  if (index < 0 || index >= path.length - 1) return null
  return { from: path[index], to: path[index + 1] }
}

export function shouldRecomputeRoute(distanceOffPathMeters: number) {
  return distanceOffPathMeters > 20
}

type Pose = { x: number; y: number; heading: number }

export function smoothPose(prev: Pose, next: Pose, alpha = 0.2): Pose {
  return {
    x: prev.x + (next.x - prev.x) * alpha,
    y: prev.y + (next.y - prev.y) * alpha,
    heading: prev.heading + (next.heading - prev.heading) * alpha
  }
}
